import unittest
from candidate import incr_list

class TestIncrList(unittest.TestCase):
    def test_incr_list_empty(self):
        self.assertEqual(incr_list([]), [])

    def test_incr_list_single_element(self):
        self.assertEqual(incr_list([1]), [2])

    def test_incr_list_multiple_elements(self):
        self.assertEqual(incr_list([1, 2, 3]), [2, 3, 4])

    def test_incr_list_negative_numbers(self):
        self.assertEqual(incr_list([-1, -2, -3]), [-0, -1, -2])

    def test_incr_list_mixed_numbers(self):
        self.assertEqual(incr_list([-1, 0, 1]), [-0, 1, 2])

    def test_incr_list_zero(self):
        self.assertEqual(incr_list([0]), [1])

    def test_incr_list_float_numbers(self):
        self.assertAlmostEqual(incr_list([1.5, 2.5]), [2.5, 3.5])

    def test_incr_list_with_none(self):
        self.assertEqual(incr_list([None]), [None])

    def test_incr_list_with_string(self):
        self.assertListEqual(incr_list(['a', 'b', 'c']), ['b', 'c', 'd'])

    def test_incr_list_with_list_in_list(self):
        self.assertEqual(incr_list([[1, 2, 3], [4, 5, 6]]), [[2, 3, 4], [5, 6, 7]])

if __name__ == '__main__':
    unittest.main()
